       return 0;
   }
   ```

2. **Custom Error Codes:**
   - For more control, you can define your own error codes and return them from functions.
   - This approach allows you to handle different types of errors more granularly.

   ```c
   #include <stdio.h>

   // Define error codes
   #define ERROR_FILE_NOT_FOUND 1
   #define ERROR_READ_FAILED 2

   int open_file(const char *filename) {
       FILE *file = fopen(filename, "r");
       if (file == NULL) {
           if (errno == ENOENT) {
               printf("Error: File not found\n");
               return ERROR_FILE_NOT_FOUND;
           } else {
               printf("Error: %s\n", strerror(errno));
               return ERROR_READ_FAILED;
           }
       }
       return 0; // Success
   }

