           // Handle error
       }
       return 0;
   }
   ```

3. **Using `setjmp` and `longjmp`:**
   - For more complex error handling, especially in recursive functions, you can use `setjmp` and `longjmp`.

   ```c
   #include <stdio.h>
   #include <setjmp.h>

   jmp_buf env;

   void function() {
       if (setjmp(env) == 0) {
           // Normal execution
       } else {
           // Error handling
           printf("Error occurred\n");
       }
   }

   int main() {
       if (setjmp(env) == 0) {
           // Simulate an error
           longjmp(env, 1);
       }
       return 0;
   }
   ```

4. **Using Structured Error Handling:**
   - For even more robust error handling, consider using structured error handling with functions that return error codes and use `setjmp`/`longjmp` for unwinding the stack.

   ```c
   #include <stdio.h>
   #include <setjmp.h>

   jmp_buf env;

   int function() {
       if (setjmp(env) == 0) {
           // Normal execution
           return 0;
       } else {
           // Error handling
           printf("Error occurred\n");
           return -1;
       }
   }

   int main() {
       if (setjmp(env) == 0) {
           // Simulate an error
           longjmp(env, 1);
       }
       return 0;
   }
   ```

Each method has its use cases, and the best approach depends on the specific requirements of your application. For simple error messages, `errno` and `perror` are sufficient. For more complex scenarios, custom error codes and structured error handling with `setjmp`/`longjmp` provide greater flexibility.

